@startuml

class Client {
  + NIN : string
  + TIN : string
  + name : string
  + address : string
}

class BicycleModel {
  + name : string
  + type : BicycleType
  + gears : int
}

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Bicycle {
  + id : string
}

class Store {
  + name : string
  + address : string
}

class Reservation {
  + pick_up_day : date
}

class Rental {
  + return_date : date
}

BicycleModel "1" -- "*" Bicycle
Client "1" -- "*" Reservation
BicycleModel "1" -- "*" Reservation
Store "1" -- "*" Reservation
Reservation "1" -- "0..1" Rental
Bicycle "1" -- "0..1" Rental
Rental "*" -- "1" Store

@enduml

